CREATE OR ALTER PROCEDURE usp_Appointment_Add
    @CustomerID       INT,
    @MechanicID       INT,
    @ServiceTypeID    INT,
    @StartTime        DATETIME,
    @BikeDescription  VARCHAR(80),
    @Notes            VARCHAR(200),
    @BookedByStaffID  INT,
    @NewAppointmentID INT OUTPUT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';

    -- 1. Work out when the job ends: the service type knows how long it takes.
    DECLARE @EndTime DATETIME;
    SELECT @EndTime = DATEADD(MINUTE, DurationMinutes, @StartTime)
    FROM ServiceType
    WHERE ServiceTypeID = @ServiceTypeID;

    -- 2. The simple checks.
    IF @EndTime IS NULL
    BEGIN
        SET @Message = 'Choose a service.';
        RETURN;
    END
    IF NOT EXISTS (SELECT * FROM Staff WHERE StaffID = @MechanicID
        AND Role = 'Mechanic' AND IsActive = 1)
    BEGIN
        SET @Message = 'Choose a mechanic.';
        RETURN;
    END
    IF @StartTime < GETDATE()
    BEGIN
        SET @Message = 'That time has already passed.';
        RETURN;
    END
    IF DATENAME(WEEKDAY, @StartTime) = 'Sunday'
    BEGIN
        SET @Message = 'The workshop is closed on Sundays.';
        RETURN;
    END
    IF CAST(@StartTime AS TIME) < '08:30' OR CAST(@EndTime AS TIME) > '17:30'
    BEGIN
        SET @Message = 'The workshop is open 08:30 to 17:30.';
        RETURN;
    END

    -- 3. The clash check: does this mechanic already have a booking that
    -- overlaps?

    IF EXISTS (SELECT *
               FROM Appointment
               WHERE MechanicID = @MechanicID
                 -- a cancelled booking does not block the slot
                 AND Status <> 'Cancelled'
                 -- the new one starts before the old one ends
                 AND @StartTime < EndTime
                 -- and ends after the old one starts
                 AND @EndTime   > StartTime)
    BEGIN
        SET @Message = 'That mechanic already has a booking in that time.';
        RETURN;
    END

    INSERT INTO Appointment
        (CustomerID, MechanicID, ServiceTypeID, StartTime, EndTime,
         BikeDescription, Notes, BookedByStaffID)
    VALUES
        (@CustomerID, @MechanicID, @ServiceTypeID, @StartTime, @EndTime,
         @BikeDescription, @Notes, @BookedByStaffID);

    SET @NewAppointmentID = SCOPE_IDENTITY();
END
GO

-- Book Aoife (mechanic 3) for a basic service (service 6) at 13:00 on the test
-- day.
-- Run it once: it books.  Run it again: the same slot is refused.
DECLARE @Day DATE, @Start DATETIME, @NewID INT, @Message VARCHAR(200);
-- tomorrow
SET @Day = DATEADD(DAY, 1, CAST(GETDATE() AS DATE));
-- the workshop is shut on Sundays
IF DATENAME(WEEKDAY, @Day) = 'Sunday' SET @Day = DATEADD(DAY, 1, @Day);
-- 13:00 on the test day
SET @Start = DATEADD(HOUR, 13, CAST(@Day AS DATETIME));

EXEC usp_Appointment_Add
     @CustomerID = 1, @MechanicID = 3, @ServiceTypeID = 6, @StartTime = @Start,
     @BikeDescription = 'Blue Trek hybrid', @Notes = NULL, @BookedByStaffID = 2,
     @NewAppointmentID = @NewID OUTPUT, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    PRINT 'Booked. New appointment number ' + CAST(@NewID AS VARCHAR) + ' at '
        + CAST(CAST(@Start AS TIME) AS VARCHAR(5)) + ' on '
        + CAST(@Day AS VARCHAR) + '.';
END
ELSE
BEGIN
    PRINT @Message;
END

CREATE OR ALTER PROCEDURE usp_Appointment_Move
    @AppointmentID INT,
    @NewStartTime  DATETIME,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';

    DECLARE @MechanicID INT, @Minutes INT, @Status VARCHAR(10);
    SELECT @MechanicID = MechanicID,
       @Minutes    = DATEDIFF(MINUTE, StartTime, EndTime),
       @Status     = Status
    FROM Appointment
    WHERE AppointmentID = @AppointmentID;

    IF @MechanicID IS NULL
    BEGIN
        SET @Message = 'That booking does not exist.';
        RETURN;
    END
    IF @Status <> 'Booked'
    BEGIN
        SET @Message = 'Only a booking that is still open can be moved.';
        RETURN;
    END

    DECLARE @NewEndTime DATETIME;
    SET @NewEndTime = DATEADD(MINUTE, @Minutes, @NewStartTime);

    IF @NewStartTime < GETDATE()
    BEGIN
        SET @Message = 'That time has already passed.';
        RETURN;
    END
    IF DATENAME(WEEKDAY, @NewStartTime) = 'Sunday'
    BEGIN
        SET @Message = 'The workshop is closed on Sundays.';
        RETURN;
    END
    IF CAST(@NewStartTime AS TIME) < '08:30'
        OR CAST(@NewEndTime AS TIME) > '17:30'
    BEGIN
        SET @Message = 'The workshop is open 08:30 to 17:30.';
        RETURN;
    END

    IF EXISTS (SELECT *
               FROM Appointment
               WHERE MechanicID = @MechanicID
                 -- a booking cannot clash with itself
                 AND AppointmentID <> @AppointmentID
                 AND Status <> 'Cancelled'
                 AND @NewStartTime < EndTime
                 AND @NewEndTime   > StartTime)
    BEGIN
        SET @Message = 'That mechanic already has a booking in that time.';
        RETURN;
    END

    UPDATE Appointment
    SET StartTime = @NewStartTime, EndTime = @NewEndTime
    WHERE AppointmentID = @AppointmentID;
END
GO

-- Book Aoife at 15:00, then move that booking three times: onto itself, to
-- 15:15, and onto her 13:00 booking.
DECLARE @Day DATE, @Start DATETIME, @B INT, @Message VARCHAR(200);
SET @Day = DATEADD(DAY, 1, CAST(GETDATE() AS DATE));
IF DATENAME(WEEKDAY, @Day) = 'Sunday' SET @Day = DATEADD(DAY, 1, @Day);
-- 15:00 on the test day
SET @Start = DATEADD(HOUR, 15, CAST(@Day AS DATETIME));

EXEC usp_Appointment_Add
     @CustomerID = 2, @MechanicID = 3, @ServiceTypeID = 6, @StartTime = @Start,
     @BikeDescription = 'Black Giant road bike', @Notes = NULL,
         @BookedByStaffID = 2,
     @NewAppointmentID = @B OUTPUT, @Message = @Message OUTPUT;
IF @Message <> ''
BEGIN
    PRINT 'Could not make the 15:00 booking: ' + @Message;
    -- stop here
    RETURN;
END
PRINT 'Booked number ' + CAST(@B AS VARCHAR) + ' at 15:00.';

-- 1. Onto its own time: a booking never clashes with itself.
EXEC usp_Appointment_Move @AppointmentID = @B, @NewStartTime = @Start,
    @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Moved onto itself: allowed.';
END
ELSE
BEGIN
    PRINT 'Moved onto itself: ' + @Message;
END

-- 2. To 15:15: the only booking it overlaps is itself, so still allowed.
SET @Start = DATEADD(MINUTE, 15, @Start);
EXEC usp_Appointment_Move @AppointmentID = @B, @NewStartTime = @Start,
    @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Moved to 15:15: allowed.';
END
ELSE
BEGIN
    PRINT 'Moved to 15:15: ' + @Message;
END

-- 3. To 13:30: inside the 13:00 booking from the stage 2 test, so refused.
SET @Start = DATEADD(HOUR, 13, CAST(@Day AS DATETIME));
SET @Start = DATEADD(MINUTE, 30, @Start);
EXEC usp_Appointment_Move @AppointmentID = @B, @NewStartTime = @Start,
    @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Moved to 13:30: allowed. (Run the stage 2 test first and this ' +
        'move is refused.)';
END
ELSE BEGIN PRINT 'Move to 13:30 refused: ' + @Message; END

CREATE OR ALTER PROCEDURE usp_Hire_Add
    @BikeID          INT,
    @CustomerID      INT,
    @StartDate       DATE,
    @EndDate         DATE,
    @DepositPaid     DECIMAL(8,2),
    @BookedByStaffID INT,
    @NewHireID       INT OUTPUT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';

    DECLARE @DailyRate DECIMAL(6,2), @Purpose VARCHAR(4), @Status VARCHAR(10);
    SELECT @DailyRate = DailyRate, @Purpose = Purpose, @Status = Status
    FROM Bike
    WHERE BikeID = @BikeID;

    IF @Purpose IS NULL OR @Purpose <> 'Hire'
    BEGIN
        SET @Message = 'Choose a hire bike.';
        RETURN;
    END
    IF @Status <> 'Available'
    BEGIN
        SET @Message = 'That bike is not available for hire.';
        RETURN;
    END
    IF @EndDate <= @StartDate
    BEGIN
        SET @Message = 'The return date must be after the start date.';
        RETURN;
    END
    IF @StartDate < CAST(GETDATE() AS DATE)
    BEGIN
        SET @Message = 'The start date has already passed.';
        RETURN;
    END

    DECLARE @Days INT;
    SET @Days = DATEDIFF(DAY, @StartDate, @EndDate);
    DECLARE @TotalCost DECIMAL(8,2);
    SET @TotalCost = @Days * @DailyRate;
    DECLARE @MinDeposit DECIMAL(8,2);
    SET @MinDeposit = ROUND(@TotalCost * 0.20, 2);

    IF @DepositPaid < @MinDeposit
    BEGIN
        SET @Message = 'The deposit must be at least £'
            + CAST(@MinDeposit AS VARCHAR)
            + ' (20% of £' + CAST(@TotalCost AS VARCHAR) + ').';
        RETURN;
    END

    IF EXISTS (SELECT *
               FROM Hire
               WHERE BikeID = @BikeID
                 AND Status IN ('Booked', 'Out')
                 -- same rule as appointments, with dates
                 AND @StartDate < EndDate
                 AND @EndDate   > StartDate)
    BEGIN
        SET @Message = 'That bike is already out on those dates.';
        RETURN;
    END

    INSERT INTO Hire (BikeID, CustomerID, StartDate, EndDate, TotalCost,
        DepositPaid, BookedByStaffID)
    VALUES (@BikeID, @CustomerID, @StartDate, @EndDate, @TotalCost,
        @DepositPaid, @BookedByStaffID);

    SET @NewHireID = SCOPE_IDENTITY();
END
GO

-- Hire bike 1 to customer 1 for three days, starting ten days from now.  Then
-- try the same bike for dates that overlap.
DECLARE @From DATE, @To DATE, @H INT, @Message VARCHAR(200);
SET @From = DATEADD(DAY, 10, CAST(GETDATE() AS DATE));
SET @To = DATEADD(DAY, 3, @From);

EXEC usp_Hire_Add @BikeID = 1, @CustomerID = 1, @StartDate = @From,
    @EndDate = @To,
     @DepositPaid = 50, @BookedByStaffID = 2, @NewHireID = @H OUTPUT,
         @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Hired. New hire number ' + CAST(@H AS VARCHAR) + ' from '
        + CAST(@From AS VARCHAR) + ' for 3 days.';
END
ELSE BEGIN PRINT 'Hire refused: ' + @Message; END

-- The same bike again, starting the day before that hire ends: the dates
-- overlap, so it must be refused.
SET @From = DATEADD(DAY, 2, @From);
SET @To = DATEADD(DAY, 3, @From);
EXEC usp_Hire_Add @BikeID = 1, @CustomerID = 2, @StartDate = @From,
    @EndDate = @To,
     @DepositPaid = 50, @BookedByStaffID = 2, @NewHireID = @H OUTPUT,
         @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'The overlapping hire got through: the rule is broken.';
END
ELSE BEGIN PRINT 'Overlapping hire refused: ' + @Message; END

