using System;
using System.Data;
using System.Data.SqlClient;
using BikeShop.Models;

namespace BikeShop.Data
{
    public static class AppointmentData
    {
        #region GetByDay
        // Every booking on one day.
        public static DataTable GetByDay(DateTime day)
        {
            return Db.GetTable("usp_Appointment_GetByDay",
                Db.P("@Day", day.Date));
        }
        #endregion

        #region GetFreeMechanics
        // The mechanics who are free for the whole length of this service,
        // starting at this time.
        public static DataTable GetFreeMechanics(DateTime startTime,
            int serviceTypeID)
        {
            return Db.GetTable("usp_Appointment_GetFreeMechanics",
                Db.P("@StartTime", startTime),
                Db.P("@ServiceTypeID", serviceTypeID));
        }
        #endregion

        // All the bookings for one customer.
        public static DataTable GetForCustomer(int customerID)
        {
            return Db.GetTable("usp_Appointment_GetForCustomer",
                Db.P("@CustomerID", customerID));
        }

        #region Add
        // Saves a new booking.  The procedure works out the end time and
        // refuses a clash.
        // Returns "" if it worked, or the sentence to show the user.
        public static string Add(Appointment appointment)
        {
            SqlParameter newID = Db.Out("@NewAppointmentID");
            string message = Db.Run("usp_Appointment_Add",
                Db.P("@CustomerID", appointment.CustomerID),
                Db.P("@MechanicID", appointment.MechanicID),
                Db.P("@ServiceTypeID", appointment.ServiceTypeID),
                Db.P("@StartTime", appointment.StartTime),
                Db.P("@BikeDescription", appointment.BikeDescription),
                Db.P("@Notes", appointment.Notes),
                Db.P("@BookedByStaffID", appointment.BookedByStaffID),
                newID);
            if (message == "")
            {
                appointment.AppointmentID = (int)newID.Value;
            }
            return message;
        }
        #endregion

        #region Move
        // Moves a booking to a new start time.  The procedure checks the new
        // time is free.
        public static string Move(int appointmentID, DateTime newStartTime)
        {
            return Db.Run("usp_Appointment_Move",
                Db.P("@AppointmentID", appointmentID),
                Db.P("@NewStartTime", newStartTime));
        }
        #endregion

        #region Cancel
        // Cancels a booking.  Returns "" if it worked.
        public static string Cancel(int appointmentID)
        {
            return Db.Run("usp_Appointment_Cancel",
                Db.P("@AppointmentID", appointmentID));
        }
        #endregion

        // Marks a booking as done.
        public static string MarkDone(int appointmentID)
        {
            return Db.Run("usp_Appointment_MarkDone",
                Db.P("@AppointmentID", appointmentID));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.Windows.Forms;
using BikeShop.Data;
using BikeShop.Models;

namespace BikeShop.Forms
{
    public partial class frmAppointmentEdit : Form
    {
        // 0 = a new booking; otherwise the booking being moved
        private readonly int appointmentID;
        // the date and time the form opens on
        private readonly DateTime startWith;
        // "Aoife McCann · Puncture repair with Conor" when moving
        private readonly string movingWhat;

        // New booking on a chosen day
        public frmAppointmentEdit(DateTime day)
        {
            InitializeComponent();
            startWith = day.Date.AddHours(9);
        }

        // Move an existing booking: only the date and time can change
        public frmAppointmentEdit(int id, DateTime currentStart, string summary)
        {
            InitializeComponent();
            appointmentID = id;
            startWith = currentStart;
            movingWhat = summary;
        }

private void frmAppointmentEdit_Load(object sender, EventArgs e)
{
    // The two text boxes stop typing at the length the database column
    // holds.
    txtBike.MaxLength = 80;
    txtNotes.MaxLength = 200;

    FillTimes();
    dtpDate.Value = startWith.Date;
    cboStart.SelectedItem = startWith.ToString("HH:mm");

    // Set the two names first, then the DataSource, so the combo box
    // knows what to show and what to keep.
    cboCustomer.DisplayMember = "FullName";
    cboCustomer.ValueMember = "CustomerID";
    cboCustomer.DataSource = CustomerData.Search("");

    // "Puncture repair · 30 min · £15.00"
    cboService.DisplayMember = "Display";
    cboService.ValueMember = "ServiceTypeID";
    cboService.DataSource = ServiceTypeData.GetAll();

    if (appointmentID != 0)
    {
        Text = "Move a booking";
        lblMoving.Text = "Moving: " + movingWhat;
        btnBook.Text = "Move";
        cboCustomer.Enabled = false;
        cboService.Enabled = false;
        cboMechanic.Enabled = false;
        txtBike.Enabled = false;
        txtNotes.Enabled = false;
        lblMechanicNote.Text = "The same mechanic keeps the job.";
    }
    else
    {
        lblMoving.Text = "";
        RefreshMechanics();
    }
}

// The shop opens 08:30 and the last slot starts 17:15: a time every 15
// minutes.
private void FillTimes()
{
    cboStart.Items.Clear();
    TimeSpan time = new TimeSpan(8, 30, 0);
    while (time <= new TimeSpan(17, 15, 0))
    {
        cboStart.Items.Add(time.ToString(@"hh\:mm"));
        time = time.Add(TimeSpan.FromMinutes(15));
    }
}

// Asks the database which mechanics are free for this service at this
// time.
// Runs again whenever the date, the time or the service changes.
private void RefreshMechanics()
{
    if (appointmentID != 0 || cboService.SelectedValue == null
        || cboStart.SelectedItem == null)
    {
        return;
    }

    cboMechanic.DisplayMember = "FullName";
    cboMechanic.ValueMember = "StaffID";
    cboMechanic.DataSource = AppointmentData.GetFreeMechanics(
        ChosenStart(), (int)cboService.SelectedValue);

    int free = cboMechanic.Items.Count;
    if (free == 0)
    {
        lblMechanicNote.Text =
            "No mechanic is free then. Try another time.";
    }
    else if (free == 1)
    {
        lblMechanicNote.Text = "1 mechanic is free.";
    }
    else
    {
        lblMechanicNote.Text = free + " mechanics are free.";
    }
    btnBook.Enabled = free > 0;
}

private void cboService_SelectedIndexChanged(object sender, EventArgs e)
{
    RefreshMechanics();
}

private void dtpDate_ValueChanged(object sender, EventArgs e)
{
    RefreshMechanics();
}

private void cboStart_SelectedIndexChanged(object sender, EventArgs e)
{
    RefreshMechanics();
}

private void btnBook_Click(object sender, EventArgs e)
{
    if (appointmentID != 0)
    {
        MoveBooking();
        return;
    }

    // Check what was chosen and typed, one problem at a time: show the
    // first and put the cursor there.
    if (ChosenID(cboCustomer) == 0)
    {
        Msg.Problem("Choose the customer.");
        cboCustomer.Focus();
        return;
    }
    if (ChosenID(cboService) == 0)
    {
        Msg.Problem("Choose the service.");
        cboService.Focus();
        return;
    }
    if (ChosenID(cboMechanic) == 0)
    {
        Msg.Problem("Choose a mechanic.");
        cboMechanic.Focus();
        return;
    }
    // The start time needs no check: the list only offers times in
    // 15-minute steps.
    if (txtBike.Text.Trim() == "")
    {
        Msg.Problem("Type a description of the bike.");
        txtBike.Focus();
        return;
    }

    Appointment booking = new Appointment();
    booking.CustomerID = ChosenID(cboCustomer);
    booking.ServiceTypeID = ChosenID(cboService);
    booking.MechanicID = ChosenID(cboMechanic);
    booking.StartTime = ChosenStart();
    booking.BikeDescription = txtBike.Text.Trim();
    booking.Notes = txtNotes.Text.Trim();
    if (booking.Notes == "")
    {
        // nothing typed: store a NULL, not an empty piece of text
        booking.Notes = null;
    }
    booking.BookedByStaffID = Session.StaffID;

    // The database checks the clash, the hours and the day, and answers
    // in words.
    string message = AppointmentData.Add(booking);
    if (message != "")
    {
        // e.g. "That mechanic already has a booking in that time."
        Msg.Problem(message);
        // the list may have changed since it was filled
        RefreshMechanics();
        return;
    }
    DialogResult = DialogResult.OK;
}

private void MoveBooking()
{
    string message = AppointmentData.Move(appointmentID, ChosenStart());
    if (message != "")
    {
        Msg.Problem(message);
        return;
    }
    DialogResult = DialogResult.OK;
}

// A combo box with nothing chosen gives null; this turns that into 0.
private int ChosenID(ComboBox combo)
{
    if (combo.SelectedValue == null)
    {
        return 0;
    }
    return (int)combo.SelectedValue;
}

